-- public.respawn_landing(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.respawn_landing(p_world uuid, p_x integer, p_y integer)
 RETURNS TABLE(x integer, y integer)
 LANGUAGE sql
 STABLE
AS $function$
  select p_x + r.dx, p_y + r.dy
    from world w
    cross join respawn_ring() r
   where w.id = p_world
     and passable(p_world, p_x + r.dx, p_y + r.dy)
     and runestone_on(w.size, p_x + r.dx, p_y + r.dy) is null
     and not has_water(p_world, p_x + r.dx, p_y + r.dy)
     and tile_slope(p_world, p_x + r.dx, p_y + r.dy) <= landing_stand()
     and building_at(p_world, p_x + r.dx, p_y + r.dy) is null
   order by r.k
   limit 1
$function$
